// enchantments component blob: {ench:[{id,lvl}], showTooltip bool}
fn enchantments_data(list: &[(i64, i64)], show_tip: bool) -> Vec<u8> {
    let mut d = Vec::new();
    write_varint(&mut d, list.len() as i64);
    for (id, lv) in list {
        write_varint(&mut d, *id);
        write_varint(&mut d, *lv);
    }
    d.push(show_tip as u8);
    d
}
fn enchantments_get(c: &Comps) -> Vec<(i64, i64)> {
    let mut out = Vec::new();
    if let Some(d) = comp_get(c, COMP_ENCHANTMENTS) {
        let (n, mut p) = read_varint_at(d, 0);
        for _ in 0..n.min(64) {
            if p + 2 > d.len() {
                break;
            }
            let (id, p2) = read_varint_at(d, p);
            let (lv, p3) = read_varint_at(d, p2);
            p = p3;
            out.push((id, lv));
        }
    }
    out
}
// vanilla 1.9+ attack cooldown: seconds per full charge by tool kind.
// sword 1.6 (0.625s); axe ~1.0s avg across tiers; hoe 1.5s; fist 0.25s.
fn attack_cooldown(item: i64) -> f64 {
    if !(818..=847).contains(&item) {
        return 0.25;
    }
    match (item - 818) % 5 {
        0 => 0.625, // sword
        1 => 1.0,   // shovel
        2 => 0.833, // pickaxe
        3 => 1.0,   // axe (0.8-1.25 by tier, 1.0 avg)
        _ => 1.5,   // hoe
    }
}

// Vanilla destroy time: damage/tick = speed/hardness/(canHarvest?30:100), so
// seconds = hardness*1.5/speed when harvestable and hardness*5.0/speed when not.
// hardness < 0 means unbreakable, 0 means instantaneous. `canHarvest` comes from
// the registry's harvestTools data; the tool *speed* side is still a hand table.
/// Vanilla destroy time, owned by the block registry, which reads it from the same
/// asset it reads everything else from. The fallback only applies if the registry
/// failed to load at all.
fn block_hardness(b: i64) -> f32 {
    match crate::block_registry::breg() {
        Some(reg) => reg.hardness_of(b as u32),
        None => 0.6,
    }
}
/// Whether this tool harvests this block, owned by the registry's `harvestTools`
/// data. It decides both the drop and the fast/slow mining multiplier, so the two
/// call sites must ask the same question.
/// Test-only: production goes through item_stack_max, which resolves the item to its
/// block first.
#[cfg(test)]
fn stack_size_of(st: u32) -> i64 {
    crate::block_registry::breg()
        .map(|reg| reg.stack_size_of(st))
        .unwrap_or(64)
}
fn tool_kind(block: i64) -> i8 {
    match crate::block_registry::breg() {
        Some(reg) => reg.tool_kind_of(block as u32),
        None => -1,
    }
}
fn can_harvest(block: i64, held_item: i64) -> bool {
    match crate::block_registry::breg() {
        Some(reg) => reg.can_harvest(block as u32, held_item),
        None => true,
    }
}
// tool dig speed; kind order in band: sword,shovel,pick,axe,hoe; tier: wood,stone,gold,iron,diamond,netherite
fn tool_dig_speed(held: &Stack, block: i64) -> f32 {
    let (kind, band) = if (818..=847).contains(&held.0) {
        ((held.0 - 818) % 5, (held.0 - 818) / 5)
    } else {
        (-1, 0)
    };
    let tier_speed = [2.0f32, 4.0, 12.0, 6.0, 8.0, 9.0];
    // The correct tool type comes from the block asset, not from id ranges: the hand
    // ranges answered for 16 percent of the states.
    let right_tool = kind >= 0 && kind == i64::from(tool_kind(block));
    let mut speed = if right_tool {
        tier_speed[band.clamp(0, 5) as usize]
    } else {
        1.0
    };
    let eff = enchant_level(&held.2, 8);
    if eff > 0 && speed > 1.0 {
        speed += (eff * eff + 1) as f32;
    }
    speed
}

fn dig_seconds(block: i64, held: &Stack) -> Option<f32> {
    let h = block_hardness(block);
    if h < 0.0 {
        return None;
    }
    if h == 0.0 {
        return Some(0.0);
    }
    let speed = tool_dig_speed(held, block);
    let can = can_harvest(block, held.0);
    Some(h * if can { 1.5 } else { 5.0 } / speed)
}

fn melee_charge(me: &Arc<Client>, item: i64) -> f32 {
    let cd = attack_cooldown(item);
    let mut lm = me.last_melee.lock().unwrap();
    let c = (lm.elapsed().as_secs_f64() / cd).min(1.0) as f32;
    *lm = Instant::now();
    c
}
fn enchantment_targets_undead(etype: i64) -> bool {
    entity_spec_by_id(etype).is_some_and(|entity| {
        matches!(
            entity.name.strip_prefix("minecraft:"),
            Some(
                "drowned"
                    | "husk"
                    | "phantom"
                    | "skeleton"
                    | "skeleton_horse"
                    | "stray"
                    | "wither"
                    | "wither_skeleton"
                    | "zombie"
                    | "zombie_horse"
                    | "zombie_villager"
                    | "zombified_piglin"
                    | "zoglin"
            )
        )
    })
}
fn enchantment_targets_arthropod(etype: i64) -> bool {
    entity_spec_by_id(etype).is_some_and(|entity| {
        matches!(
            entity.name.strip_prefix("minecraft:"),
            Some("bee" | "cave_spider" | "endermite" | "silverfish" | "spider")
        )
    })
}
fn melee_critical_allowed(
    charge: f32,
    grounded: bool,
    falling: bool,
    fall_flying: bool,
    sprinting: bool,
    in_water: bool,
    climbing: bool,
    blind: bool,
) -> bool {
    charge > 0.9
        && !grounded
        && falling
        && !fall_flying
        && !sprinting
        && !in_water
        && !climbing
        && !blind
}
fn fire_aspect_duration_ticks(level: i64) -> i32 {
    server_ticks(80 * level.max(0) as u64) as i32
}
fn fire_tick_update(remaining: i32, tick: u64, fire_immune: bool) -> (i32, bool) {
    let damage = remaining > 0
        && tick.is_multiple_of(server_ticks(MOB_BURN_TICK_GT))
        && !fire_immune;
    (remaining.saturating_sub(1).max(0), damage)
}
fn enchant_level(c: &Comps, id: i64) -> i64 {
    enchantments_get(c)
        .iter()
        .find(|(e, _)| *e == id)
        .map(|(_, l)| *l)
        .unwrap_or(0)
}
fn enchant_max_level(id: i64) -> i64 {
    match id {
        0 | 2 | 12 | 16 | 22 | 23 | 33 | 40 => 1, // aqua..infinity,mending,multishot,silk,vanishing
        14 | 17 | 10 | 28 => 2,                   // frost, knockback, fire_aspect, punch
        7 | 13 | 18 | 19 | 20 | 21 | 29 | 30 | 31 | 35 | 36 | 37 | 38 | 39 | 41 => 3,
        3 | 4 | 9 | 11 | 24 | 26 | 27 => 4, // protection family, feather, breach, piercing
        _ => 5,                             // damage/efficiency/power/impaling/density
    }
}
// vanilla mutually-exclusive groups; some/any overlap forbids
fn enchant_conflicts(a: i64, b: i64) -> bool {
    const GROUPS: &[&[i64]] = &[
        &[27, 3, 11, 26],   // protection family
        &[32, 34, 1, 6, 4], // sharpness/smite/bane/density/breach
        &[33, 13],          // silk_touch vs fortune
        &[16, 22],          // infinity vs mending
        &[31, 19, 5],       // riptide vs loyalty/channeling
        &[7, 14],           // depth_strider vs frost_walker
        &[23, 24],          // multishot vs piercing
    ];
    a != b && GROUPS.iter().any(|g| g.contains(&a) && g.contains(&b))
}
// TAG_String anonymous-NBT payload: type byte + modified-UTF-8 string.
fn nbt_string(text: &str) -> Vec<u8> {
    let mut d = vec![8u8];
    nbt_str(&mut d, text);
    d
}
// parse the [k=v,...] suffix of a /give item argument; supported subset:
// enchantments={a:lvl,...}, damage, max_damage, unbreakable, custom_name,
// lore, max_stack_size, repair_cost. Unknown/unsupported keys are ignored
// (bounded: no silent half-support claims).
fn parse_item_comps(arg: &str) -> Comps {
    let Some(lb) = arg.find('[') else {
        return Vec::new();
    };
    let Some(rb) = arg.rfind(']') else {
        return Vec::new();
    };
    if rb <= lb {
        return Vec::new();
    }
    let mut out: Comps = Vec::new();
    // split on top-level commas only — {}, [], '' nesting must not break
    let body = &arg[lb + 1..rb];
    let mut kvs: Vec<String> = Vec::new();
    {
        let mut depth = 0i32;
        let mut q = '\0';
        let mut cur = String::new();
        for ch in body.chars() {
            if q != '\0' {
                cur.push(ch);
                if ch == q {
                    q = '\0';
                }
                continue;
            }
            match ch {
                '\'' | '"' => {
                    q = ch;
                    cur.push(ch)
                }
                '{' | '[' | '(' => {
                    depth += 1;
                    cur.push(ch)
                }
                '}' | ']' | ')' => {
                    depth -= 1;
                    cur.push(ch)
                }
                ',' if depth == 0 => {
                    kvs.push(std::mem::take(&mut cur));
                }
                _ => cur.push(ch),
            }
        }
        if !cur.is_empty() {
            kvs.push(cur);
        }
    }
    for kv in &kvs {
        let kv = kv.trim();
        let (k, v) = match kv.split_once('=') {
            Some(t) => t,
            None => (kv, ""),
        };
        let kn = k.trim().trim_start_matches("minecraft:");
        match kn {
            "enchantments" => {
                // {name:lvl,...} — vanilla 1.21.1 map form
                let inner = v.trim().trim_start_matches('{').trim_end_matches('}');
                let mut list: Vec<(i64, i64)> = enchantments_get(&out);
                for e in inner.split(',') {
                    if let Some((en, lv)) = e.rsplit_once(':') {
                        let en = en.trim().trim_matches('"').trim_matches('\'');
                        if let (Some(id), Ok(l)) = (enchant_id(en), lv.trim().parse::<i64>()) {
                            list.retain(|(x, _)| *x != id);
                            list.push((id, l.max(1)));
                        }
                    }
                }
                comp_set(&mut out, COMP_ENCHANTMENTS, enchantments_data(&list, true));
            }
            "damage" => {
                if let Ok(n) = v.parse() {
                    comp_set_varint(&mut out, COMP_DAMAGE, n)
                }
            }
            "max_damage" => {
                if let Ok(n) = v.parse() {
                    comp_set_varint(&mut out, COMP_MAX_DAMAGE, n)
                }
            }
            "max_stack_size" => {
                if let Ok(n) = v.parse() {
                    comp_set_varint(&mut out, 1, n)
                }
            }
            "repair_cost" => {
                if let Ok(n) = v.parse() {
                    comp_set_varint(&mut out, 16, n)
                }
            }
            "unbreakable" => comp_set(&mut out, COMP_UNBREAKABLE, vec![1u8]),
            "custom_name" => {
                let t = v.trim().trim_matches('\'').trim_matches('"');
                comp_set(&mut out, COMP_CUSTOM_NAME, nbt_string(t));
            }
            "potion_contents" => {
                let potion = v.trim().trim_matches(['\'', '"']);
                let potion = potion.strip_prefix("minecraft:").unwrap_or(potion);
                if let Some(id) = LIVE_POTIONS.iter().position(|&(name, _)| name == potion) {
                    let mut data = vec![1];
                    write_varint(&mut data, id as i64);
                    data.extend([0, 0]); // no custom color or custom effects
                    comp_set(&mut out, COMP_POTION_CONTENTS, data);
                }
            }
            "lore" => {
                // ['a','b',...] — list of anonymous-NBT string elements
                let inner = v.trim().trim_start_matches('[').trim_end_matches(']');
                let mut d = Vec::new();
                let parts: Vec<String> = inner
                    .split(',')
                    .map(|x| x.trim().trim_matches('\'').trim_matches('"').to_string())
                    .filter(|x| !x.is_empty())
                    .collect();
                write_varint(&mut d, parts.len() as i64);
                for t in parts {
                    d.extend_from_slice(&nbt_string(&t));
                }
                comp_set(&mut out, COMP_LORE, d);
            }
            _ => {}
        }
    }
    out
}
// vanilla enchantability, approximated: damageable items accept
// unbreaking/mending always; weapons/tools/armor accept their usual sets.
fn enchant_applicable(item: i64, eid: i64) -> bool {
    let band = if (818..=847).contains(&item) {
        Some(((item - 818) / 5, (item - 818) % 5))
    } else {
        None
    };
    let bow = item == name_to_item("bow").unwrap_or(-1);
    let xbow = item == name_to_item("crossbow").unwrap_or(-2);
    let trident = item == name_to_item("trident").unwrap_or(-3);
    let rod = item == name_to_item("fishing_rod").unwrap_or(-4);
    let mace = item == name_to_item("mace").unwrap_or(-5);
    let armor = (1064..=1115).contains(&item); // leather..netherite armor band
    match eid {
        39 | 22 => tool_max_damage(item).is_some() || band.is_some() || armor, // unbreaking/mending
        32 | 34 | 1 | 17 | 10 | 18 | 36 => {
            band.map(|(_, k)| k == 0 || k == 3).unwrap_or(false) || mace
        } // melee
        8 | 13 | 33 => band.map(|(_, k)| (1..=4).contains(&k)).unwrap_or(false), // efficiency/fortune/silk
        25 | 28 | 12 | 16 => bow,    // power/punch/flame/infinity
        29 | 23 | 24 => xbow,        // quick_charge/multishot/piercing
        19 | 31 | 5 | 15 => trident, // loyalty/riptide/channeling/impaling
        20 | 21 => rod,              // luck_of_the_sea/lure
        27 | 3 | 11 | 26 | 38 | 0 | 7 | 9 | 14 | 30 | 35 | 37 | 2 | 40 => armor, // armor enchants+curses
        6 | 4 | 41 => mace, // density/breach/wind_burst
        _ => true,
    }
}
// damage the held item by 1 point (unbreaking roll applied); returns
// true if the item broke. Vanilla: tools pay 1 per block broken /
// melee hit; unbreaking gives 1/(level+1) chance of actual damage.
fn damage_held(me: &Arc<Client>) -> bool {
    let hs = *me.held.lock().unwrap();
    let mut inv = me.inv.lock().unwrap();
    let slot = 36 + hs;
    let Some(st) = inv.get_mut(&slot) else {
        return false;
    };
    let Some(maxd) = tool_max_damage(st.0).or_else(|| comp_varint(&st.2, COMP_MAX_DAMAGE)) else {
        return false;
    };
    if comp_get(&st.2, COMP_UNBREAKABLE).is_some() {
        return false;
    }
    let unb = enchant_level(&st.2, 39); // unbreaking
    if unb > 0 && !world_rng::next_u64().is_multiple_of((unb + 1) as u64) {
        return false;
    }
    let dmg = comp_varint(&st.2, COMP_DAMAGE).unwrap_or(0) + 1;
    if dmg >= maxd {
        inv.remove(&slot);
        return true;
    }
    comp_set_varint(&mut st.2, COMP_DAMAGE, dmg);
    false
}
// same durability tick on an arbitrary inventory slot (elytra wear, etc)
fn damage_inv_slot(me: &Arc<Client>, slot: i16) -> bool {
    let mut inv = me.inv.lock().unwrap();
    let Some(st) = inv.get_mut(&slot) else {
        return false;
    };
    let Some(maxd) = tool_max_damage(st.0)
        .or_else(|| armor_max_damage(st.0))
        .or_else(|| comp_varint(&st.2, COMP_MAX_DAMAGE))
    else {
        return false;
    };
    if comp_get(&st.2, COMP_UNBREAKABLE).is_some() {
        return false;
    }
    let unb = enchant_level(&st.2, 39);
    if unb > 0 && !world_rng::next_u64().is_multiple_of((unb + 1) as u64) {
        return false;
    }
    let dmg = comp_varint(&st.2, COMP_DAMAGE).unwrap_or(0) + 1;
    if dmg >= maxd {
        inv.remove(&slot);
        return true;
    }
    comp_set_varint(&mut st.2, COMP_DAMAGE, dmg);
    false
}
// vanilla: blocking with a shield pays floor(blocked)+1 durability
fn damage_shield(me: &Arc<Client>, blocked: f32) {
    let sh = name_to_item("shield").unwrap_or(-9);
    let slots = [45i16, 36 + *me.held.lock().unwrap()];
    let mut inv = me.inv.lock().unwrap();
    for slot in slots {
        let Some(st) = inv.get_mut(&slot) else {
            continue;
        };
        if st.0 != sh {
            continue;
        }
        if comp_get(&st.2, COMP_UNBREAKABLE).is_some() {
            return;
        }
        let unb = enchant_level(&st.2, 39);
        let maxd = comp_varint(&st.2, COMP_MAX_DAMAGE).unwrap_or(337);
        let mut add = 0i64;
        for _ in 0..(blocked.floor() as i64 + 1) {
            if unb == 0 || world_rng::next_u64().is_multiple_of((unb + 1) as u64) {
                add += 1
            }
        }
        let dmg = comp_varint(&st.2, COMP_DAMAGE).unwrap_or(0) + add;
        if dmg >= maxd {
            inv.remove(&slot);
        } else {
            comp_set_varint(&mut st.2, COMP_DAMAGE, dmg);
        }
        return;
    }
}
// vanilla hurtArmor: each worn piece pays max(1, floor(raw/4)); each
// piece rolls its own Unbreaking. Returns slots that broke (for resync).
fn damage_armor(me: &Arc<Client>, raw_dmg: f32) {
    let per = (raw_dmg / 4.0).floor().max(1.0) as i64;
    let mut broke = false;
    {
        let mut inv = me.inv.lock().unwrap();
        for slot in [5i16, 6, 7, 8] {
            let Some(st) = inv.get_mut(&slot) else {
                continue;
            };
            let Some(maxd) = armor_max_damage(st.0).or_else(|| comp_varint(&st.2, COMP_MAX_DAMAGE))
            else {
                continue;
            };
            if comp_get(&st.2, COMP_UNBREAKABLE).is_some() {
                continue;
            }
            let unb = enchant_level(&st.2, 39);
            let mut add = 0i64;
            for _ in 0..per {
                if unb == 0 || world_rng::next_u64().is_multiple_of((unb + 1) as u64) {
                    add += 1
                }
            }
            let dmg = comp_varint(&st.2, COMP_DAMAGE).unwrap_or(0) + add;
            if dmg >= maxd {
                inv.remove(&slot);
                broke = true;
            } else {
                comp_set_varint(&mut st.2, COMP_DAMAGE, dmg);
            }
        }
        *me.armor_pts.lock().unwrap() = armor_pts_of(&inv);
    }
    if broke {
        let (x, y, z, ..) = {
            let p = me.pos.lock().unwrap();
            *p
        };
        let snd = sound_pkt_named("entity.item.break", x, y + 1.0, z);
        broadcast(-1, |_c| (0x68, snd.clone()));
    }
    // resync the four armor slots (cheap: keeps client honest)
    for slot in [5i16, 6, 7, 8] {
        let st = me
            .inv
            .lock()
            .unwrap()
            .get(&slot)
            .cloned()
            .unwrap_or((0, 0, Vec::new()));
        let mut p = vec![0u8];
        write_varint(&mut p, 0);
        p.extend_from_slice(&slot.to_be_bytes());
        p.extend_from_slice(&slot_wire(&st));
        if let Ok(mut w) = me.sock.lock() {
            let _ = send_packet(&mut w, 0x15, p);
        }
    }
}
// resend the held slot to the owner after damage/break so the client
// model stays honest
fn held_slot_resync(me: &Arc<Client>) {
    let hs = *me.held.lock().unwrap();
    let slot = 36 + hs;
    let st = me
        .inv
        .lock()
        .unwrap()
        .get(&slot)
        .cloned()
        .unwrap_or((0, 0, Vec::new()));
    let mut p = vec![0u8];
    write_varint(&mut p, 0);
    p.extend_from_slice(&slot.to_be_bytes());
    p.extend_from_slice(&slot_wire(&st));
    if let Ok(mut w) = me.sock.lock() {
        let _ = send_packet(&mut w, 0x15, p);
    }
}
fn read_varint_at(b: &[u8], p: usize) -> (i64, usize) {
    let mut r: i64 = 0;
    let mut i = 0;
    loop {
        let byte = b[p + i];
        r |= ((byte & 0x7f) as i64) << (7 * i);
        if byte & 0x80 == 0 {
            return (r, p + i + 1);
        }
        i += 1;
    }
}
struct Drop {
    eid: i32,
    x: f64,
    y: f64,
    z: f64,
    item: i64,
    cnt: u8,
    comps: Comps,
    age: i32,
    target: Option<[u8; 16]>,
    thrower: Option<[u8; 16]>,
}
impl Drop {
    /// Vanilla keeps an ItemEntity out of reach for its pickup delay. Both collectors of a
    /// drop ask this one question: the fake-actor absorb and the real client's take. The
    /// client path did not ask it, so a player standing on a drop collected it on the tick
    /// it spawned while the actor path refused the same entity. The age read here is the
    /// live entity's, counted in server ticks by the pass that also expires it, so the
    /// delay keeps its existing cadence instead of gaining a second clock.
    fn pickup_delay_elapsed(&self) -> bool {
        self.age >= server_ticks(PICKUP_DELAY_GT) as i32
    }

    /// 1.21.1 `EntityType.ITEM` (`bsx.ag`): `sized(0.25f, 0.25f)` via `EntityDimensions.makeBoundingBox`
    /// (`bsu.a(DDD)`): `[x - 0.125, x + 0.125] x [y, y + 0.25] x [z - 0.125, z + 0.125]`.
    fn bounding_box(&self) -> EntityAabb {
        EntityAabb::from_dimensions(self.x, self.y, self.z, 0.25, 0.25)
    }

    /// 1.21.1 `Player.aiStep()` (`cmx.m_()`) + `ItemEntity.playerTouch(Player)` (`cjh.b_(Lcmx;)V`):
    /// alive non-spectator whose inflated bounding box intersects the drop's bounding box, and
    /// `target == null || target.equals(player.getUUID())`. `thrower` (`cjh.l`) is not gated here.
    fn can_be_picked_up_by_parts(
        target: Option<[u8; 16]>,
        drop_aabb: EntityAabb,
        collector_uuid: Option<[u8; 16]>,
        spectator: bool,
        alive: bool,
        player_aabb: EntityAabb,
    ) -> bool {
        if spectator || !alive {
            return false;
        }
        let target_ok = match (target, collector_uuid) {
            (None, _) => true,
            (Some(owner), Some(uuid)) => owner == uuid,
            (Some(_), None) => false,
        };
        target_ok && player_aabb.intersects(drop_aabb)
    }

    fn can_be_picked_up_by(
        &self,
        uuid: Option<[u8; 16]>,
        spectator: bool,
        alive: bool,
        player_aabb: EntityAabb,
    ) -> bool {
        Self::can_be_picked_up_by_parts(
            self.target,
            self.bounding_box(),
            uuid,
            spectator,
            alive,
            player_aabb,
        )
    }
}
static DROPS: OnceLock<Mutex<Vec<Drop>>> = OnceLock::new();
fn drops() -> &'static Mutex<Vec<Drop>> {
    DROPS.get_or_init(|| Mutex::new(Vec::new()))
}

// blockstate -> dropped item id (vanilla: stone->cobblestone, grass->dirt)
/// The item a block drops, owned by the block registry, which reads it from the same
/// asset everything else comes from. The hand table this replaced listed 13 states out
/// of the 23364 the asset gives a drop, so granite, the stairs and the slabs dropped
/// nothing at all, and glass dropped itself where vanilla drops nothing without silk
/// touch. The fallback only applies if the registry failed to load.
fn block_drop(st: u32) -> Option<i64> {
    crate::block_registry::breg().and_then(|reg| reg.block_drop(st))
}
/// The second drop, for the blocks whose asset entry lists two. Nothing is lost when a block has
/// only one: the list is filtered to the entries that exist.
fn block_drops(st: u32) -> Vec<i64> {
    let reg = crate::block_registry::breg();
    let first = reg.and_then(|r| r.block_drop(st));
    let second = reg.and_then(|r| r.block_drop_second(st));
    [first, second].into_iter().flatten().collect()
}
fn spawn_drop_pkt(d: &Drop) -> Vec<u8> {
    let mut p = Vec::new();
    write_varint(&mut p, d.eid as i64);
    p.extend_from_slice(&[0u8; 16]);
    write_varint(&mut p, 58); // item entity
    p.extend_from_slice(&d.x.to_be_bytes());
    p.extend_from_slice(&d.y.to_be_bytes());
    p.extend_from_slice(&d.z.to_be_bytes());
    p.extend_from_slice(&[0u8; 3]);
    write_varint(&mut p, 0);
    p.extend_from_slice(&[0u8; 6]);
    p
}
fn drop_meta_pkt(d: &Drop) -> Vec<u8> {
    let mut p = Vec::new();
    write_varint(&mut p, d.eid as i64);
    p.push(8); // metadata key 8 = item
    write_varint(&mut p, 7); // type 7 = item_stack
    write_varint(&mut p, d.cnt as i64); // slot: count
    write_varint(&mut p, d.item); // item id
    write_varint(&mut p, d.comps.len() as i64);
    write_varint(&mut p, 0);
    for (ty, data) in &d.comps {
        write_varint(&mut p, *ty);
        p.extend_from_slice(data);
    }
    p.push(0xff);
    p
}
fn collect_pkt(drop_eid: i32, collector: i32, count: u8) -> Vec<u8> {
    let mut p = Vec::new();
    write_varint(&mut p, drop_eid as i64);
    write_varint(&mut p, collector as i64);
    write_varint(&mut p, count as i64);
    p
}
#[cfg(test)]
fn xp_level(total: i64) -> (i32, f32) {
    let mut l = 0i32;
    let mut acc = 0i64;
    let mut next = 7i64;
    while total >= acc + next {
        acc += next;
        l += 1;
        next = xp_needed_for_next_level(l);
    }
    (l, ((total - acc) as f32 / next as f32).clamp(0.0, 1.0))
}
fn xp_orb_pkt(eid: i32, x: f64, y: f64, z: f64, count: i16) -> Vec<u8> {
    let mut p = Vec::new();
    write_varint(&mut p, eid as i64);
    p.extend_from_slice(&x.to_be_bytes());
    p.extend_from_slice(&y.to_be_bytes());
    p.extend_from_slice(&z.to_be_bytes());
    p.extend_from_slice(&count.to_be_bytes());
    p
}
fn velocity_pkt(eid: i32, vx: i16, vy: i16, vz: i16) -> Vec<u8> {
    let mut p = Vec::new();
    write_varint(&mut p, eid as i64);
    p.extend_from_slice(&vx.to_be_bytes());
    p.extend_from_slice(&vy.to_be_bytes());
    p.extend_from_slice(&vz.to_be_bytes());
    p
}
fn explosion_pkt(x: f64, y: f64, z: f64, records: &[(i8, i8, i8)]) -> Vec<u8> {
    explosion_pkt_with_power(x, y, z, 3.0, records)
}
fn explosion_pkt_with_power(
    x: f64, y: f64, z: f64, power: f32, records: &[(i8, i8, i8)],
) -> Vec<u8> {
    let mut p = Vec::new();
    p.extend_from_slice(&x.to_be_bytes());
    p.extend_from_slice(&y.to_be_bytes());
    p.extend_from_slice(&z.to_be_bytes());
    p.extend_from_slice(&power.to_be_bytes());
    write_varint(&mut p, records.len() as i64);
    for &(ox, oy, oz) in records {
        p.push(ox as u8);
        p.push(oy as u8);
        p.push(oz as u8);
    }
    p.extend_from_slice(&[0u8; 12]); // player motion xyz f32
    write_varint(&mut p, 0); // block_interaction = destroy
    write_varint(&mut p, 53); // small particle: poof
    write_varint(&mut p, 22); // large particle: explosion
    write_varint(&mut p, 577); // sound: entity.generic.explode
    p
}
// vanilla xp on death: hostile mobs 5, animals 1-3
fn mob_xp(etype: i64) -> i16 {
    if [22i64, 19, 77, 87].contains(&etype) {
        (1 + world_rng::next_u64() % 3) as i16
    } else {
        5
    }
}
// vanilla /kill applies void damage — the same loot+xp+cleanup path as
// combat death, not a silent retain
fn kill_mob(deid: i32, etype: i64, mx: f64, my: f64, mz: f64) {
    let Some((mob, state)) = remove_live_mob(deid) else { return };
    let burning = *mob.fire_ticks.lock().unwrap() > 0;
    live_mob_death(&mob, state, [mx, my, mz]);
    broadcast_seen_destroy(deid);
    let was_sheared = sheared().lock().unwrap().remove(&deid);
    for (item, cnt, comps) in mob_loot(etype, burning)
        .into_iter()
        .filter(|st| !(was_sheared && st.0 == 202))
        .filter(|_| GR_MOB_LOOT.load(Ordering::Relaxed) == 1)
    {
        let d = Drop {
            eid: NEXT_EID.fetch_add(1, Ordering::SeqCst),
            x: mx,
            y: my,
            z: mz,
            item,
            cnt,
            comps,
            age: 0,
            target: None,
            thrower: None,
        };
        drops().lock().unwrap().push(d);
    }
    let xeid = NEXT_EID.fetch_add(1, Ordering::SeqCst);
    xps().lock().unwrap().push(Xp {
        eid: xeid,
        x: mx,
        y: my,
        z: mz,
        val: mob_xp(etype),
        age: 0,
    });
    // spawn streams via interest_tick
}
fn mob_snap_y(m: &Arc<Mob>, mp: &mut (f64, f64, f64, f32, f32)) -> Option<((i32, i32, i32), f32)> {
    // A mob in water or lava has its vertical motion owned by `LivingEntity.travel`
    // (`mob_fluid_travel_tick`), so the surface snap must not teleport it to the bed.
    if mob_has_support(m.etype, mp.0, mp.1, mp.2)
        || mob_in_water(m.etype, mp.0, mp.1, mp.2)
        || mob_in_lava(m.etype, mp.0, mp.1, mp.2)
    {
        return None;
    }
    // snap to ground surface; while buried only allow snaps within step height
    // so a fully enclosed mob cannot teleport out through solid blocks
    let (land_x, land_z) = (mp.0.floor() as i32, mp.2.floor() as i32);
    let mut sy = surface_y(land_x, land_z);
    let mut landed_in_water = false;
    while sy > MIN_Y as f64 {
        let below = block_at(land_x, sy as i32 - 1, land_z);
        if !fluid_blocks_motion(below)
            && entity_fluid_state_of(below).is_some_and(|fs| fs.kind == EntityFluidKind::Water)
        {
            landed_in_water = true;
            sy -= 1.0;
        } else {
            break;
        }
    }
    if (4286..=4293).contains(&block_at(land_x, sy as i32 - 1, land_z)) {
        sy -= 1.0 / 16.0;
    }
    if !mob_cell_solid(mp.0, mp.1, mp.2) || sy - mp.1 <= 1.2 {
        // refuse snaps that phase through solid blocks (e.g. sealed under a cap)
        let (fx, fz) = (land_x, land_z);
        let mut yy = mp.1.floor() as i32 + 1;
        while yy < sy.floor() as i32 {
            if !mob_passable(block_at(fx, yy, fz)) {
                return None;
            }
            yy += 1;
        }
        landed_in_water |= mob_in_water(m.etype, mp.0, sy, mp.2);
        let landing = (!landed_in_water).then_some((
            (land_x, (sy - 0.2).floor() as i32, land_z),
            (mp.1 - sy) as f32,
        ));
        // fall damage on descent >3 blocks; chicken/cat/ocelot immune (vanilla); water resets fall distance
        if !landed_in_water && mp.1 - sy > 3.0 && !matches!(m.etype, 19 | 15 | 72) {
            let mut hp = m.hp.lock().unwrap();
            *hp -= (mp.1 - sy - 3.0).floor() as f32;
            drop(hp);
            broadcast_seen(m.eid, |_c| (0x24, hurt_anim(m.eid)));
        }
        mp.1 = sy;
        return landing;
    }
    None
}
fn mob_env_die(deid: i32, etype: i64, mx: f64, my: f64, mz: f64, burning: bool) {
    // environmental death (suffocation/drowning/fall): drops but no XP —
    // vanilla only drops XP when recently hurt by a player
    let Some((mob, state)) = remove_live_mob(deid) else { return };
    live_mob_death(&mob, state, [mx, my, mz]);
    broadcast_seen_destroy(deid);
    sheared().lock().unwrap().remove(&deid);
    for (item, cnt, comps) in mob_loot(etype, burning)
        .into_iter()
        .filter(|_| GR_MOB_LOOT.load(Ordering::Relaxed) == 1)
    {
        drops().lock().unwrap().push(Drop {
            eid: NEXT_EID.fetch_add(1, Ordering::SeqCst),
            x: mx,
            y: my,
            z: mz,
            item,
            cnt,
            comps,
            age: 0,
            target: None,
            thrower: None,
        });
    }
}
static LOOT_SEQ: AtomicU64 = AtomicU64::new(0);
fn roll_loot(pools: &[LootPool]) -> Vec<Stack> {
    let mut out: Vec<Stack> = Vec::new();
    for pl in pools {
        let h = LOOT_SEQ
            .fetch_add(1, Ordering::Relaxed)
            .wrapping_mul(6364136223846793005)
            ^ TICK.load(Ordering::Relaxed);
        if pl.chance < 1.0 && (h % 1000) as f32 / 1000.0 > pl.chance {
            continue;
        }
        for r in 0..pl.rolls {
            let e = &pl.entries[((h >> (r * 8 + 3)) as usize) % pl.entries.len()];
            let span = (e.max - e.min + 1) as u64;
            let cnt = e.min + (((h >> (r * 8 + 17)) % span.max(1)) as u8);
            if cnt > 0 {
                let mut st: Stack = (e.item, cnt, Vec::new());
                apply_loot_funcs(&mut st, &pl.funcs);
                apply_loot_funcs(&mut st, &e.funcs);
                out.push(st);
            }
        }
    }
    out
}
fn roll_loot_seeded(pools: &[LootPool], seed: i64) -> Vec<Stack> {
    let mut rng = crate::generation_math::Lcg::new(seed as u64);
    let mut out: Vec<Stack> = Vec::new();
    for pl in pools {
        if pl.chance < 1.0 && rng.next_f32() > pl.chance {
            continue;
        }
        for _ in 0..pl.rolls {
            if pl.entries.is_empty() {
                continue;
            }
            let idx = rng.next_bound(pl.entries.len() as i32) as usize;
            let e = &pl.entries[idx];
            let span = (e.max - e.min + 1) as i32;
            let cnt = e.min + (rng.next_bound(span.max(1)) as u8);
            if cnt > 0 {
                let mut st: Stack = (e.item, cnt, Vec::new());
                apply_loot_funcs(&mut st, &pl.funcs);
                apply_loot_funcs(&mut st, &e.funcs);
                out.push(st);
            }
        }
    }
    out
}
fn cooked_drop(item: i64) -> Option<i64> {
    for (r, c) in [
        ("beef", "cooked_beef"),
        ("chicken", "cooked_chicken"),
        ("porkchop", "cooked_porkchop"),
        ("mutton", "cooked_mutton"),
        ("rabbit", "cooked_rabbit"),
        ("cod", "cooked_cod"),
        ("salmon", "cooked_salmon"),
        ("potato", "baked_potato"),
    ] {
        if name_to_item(r) == Some(item) {
            return name_to_item(c);
        }
    }
    None
}
fn mob_loot(etype: i64, burning: bool) -> Vec<Stack> {
    if let Some(pools) = mob_loot_tables().lock().unwrap().get(&etype).map(|p| {
        p.iter()
            .map(|pl| LootPool {
                rolls: pl.rolls,
                chance: pl.chance,
                funcs: pl.funcs.clone(),
                entries: pl
                    .entries
                    .iter()
                    .map(|e| LootEntry {
                        item: e.item,
                        min: e.min,
                        max: e.max,
                        funcs: e.funcs.clone(),
                    })
                    .collect(),
            })
            .collect::<Vec<_>>()
    }) {
        return roll_loot(&pools)
            .into_iter()
            .map(|mut st| {
                if burning {
                    if let Some(c) = cooked_drop(st.0) {
                        st.0 = c;
                    }
                }
                st
            })
            .collect();
    }
    let names: &[&str] = match etype {
        124 => &["rotten_flesh"],
        22 => &["beef", "leather"],
        23 => &["gunpowder"],
        91 => &["bone", "arrow"],
        19 => &["chicken", "feather"],
        77 => &["porkchop"],
        87 => &["mutton", "white_wool"],
        _ => &[],
    };
    names
        .iter()
        .filter_map(|n| name_to_item(n).map(|i| (i, 1u8, Vec::new())))
        .map(|mut st| {
            if burning {
                if let Some(c) = cooked_drop(st.0) {
                    st.0 = c;
                }
            }
            st
        })
        .collect()
}

// vanilla mob damage scales with difficulty: easy min(d/2+1,d),
// normal d, hard d*1.5; peaceful hostiles don't exist.
fn diff_mob_dmg(d: f32) -> f32 {
    match DIFFICULTY.load(Ordering::Relaxed) {
        0 => 0.0,
        1 => (d / 2.0 + 1.0).min(d),
        3 => d * 1.5,
        _ => d,
    }
}
// explosion damage scales differently: easy x0.5, hard x1.5
fn diff_expl_dmg(d: f32) -> f32 {
    match DIFFICULTY.load(Ordering::Relaxed) {
        0 => 0.0,
        1 => d * 0.5,
        3 => d * 1.5,
        _ => d,
    }
}
fn armor_mult(c: &Client) -> f32 {
    let pts = *c.armor_pts.lock().unwrap();
    (1.0 - 0.04 * pts as f32).max(0.2)
}
// vanilla EPF: protection-family enchantments on worn armor add a
// post-armor reduction of min(epf,20)*4%. kind: 0 generic (prot only),
// 1 fall (feather_falling 3x), 2 explosion (blast 2x), 3 projectile
// (proj 2x), 4 fire (fire_prot 2x)
fn enchant_epf(c: &Client, kind: u8) -> i64 {
    let inv = c.inv.lock().unwrap();
    let mut epf = 0i64;
    for slot in [5i16, 6, 7, 8] {
        if let Some((_, _, comps)) = inv.get(&slot) {
            epf += enchant_level(comps, 27); // protection
            match kind {
                1 => epf += 3 * enchant_level(comps, 9),  // feather_falling
                2 => epf += 2 * enchant_level(comps, 3),  // blast_protection
                3 => epf += 2 * enchant_level(comps, 26), // projectile_protection
                4 => epf += 2 * enchant_level(comps, 11), // fire_protection
                _ => {}
            }
        }
    }
    epf.min(20)
}
fn dmg_after(c: &Client, raw: f32, kind: u8) -> f32 {
    let arm = raw * armor_mult(c);
    arm * (1.0 - 0.04 * enchant_epf(c, kind) as f32)
}
// call AFTER the hp write: if hp hit 0 and a totem is held (main or
// offhand), consume it — vanilla sets hp to 1, fires entity_status 35,
// plays the totem animation+sound, grants absorption/regen/fire_resist
fn totem_check(c: &Client) {
    if *c.hp.lock().unwrap() > 0.0 || *c.gm.lock().unwrap() == 1 {
        return;
    }
    let mut inv = c.inv.lock().unwrap();
    let held_k = 36i16 + (*c.held.lock().unwrap());
    for k in [45i16, held_k] {
        if inv.get(&k).map(|v| v.0) == Some(1163) {
            let st = inv.get(&k).unwrap().clone();
            if st.1 <= 1 {
                inv.remove(&k);
            } else {
                inv.insert(k, (st.0, st.1 - 1, st.2));
            }
            let now = inv.get(&k).cloned().unwrap_or((0, 0, Vec::new()));
            drop(inv);
            *c.hp.lock().unwrap() = 1.0;
            resync_slot(c, 0, k, &now);
            // entity_status 35 = totem use; i32 entity id + i8 status
            let mut st_pkt = Vec::new();
            st_pkt.extend_from_slice(&c.eid.to_be_bytes());
            st_pkt.push(35);
            let _ = send_packet(&mut c.sock.lock().unwrap(), 0x1f, st_pkt.clone());
            broadcast_seen(c.eid, |_c| (0x1f, st_pkt.clone()));
            let (px, py, pz, ..) = {
                let p = c.pos.lock().unwrap();
                *p
            };
            let snd = sound_pkt_named("item.totem.use", px, py, pz);
            broadcast_seen(c.eid, |_c| (0x68, snd.clone()));
            // Death protection replaces existing effects with the vanilla grant set.
            grant_totem_effects(c, &mut c.effs.lock().unwrap());
            let _ = send_packet(&mut c.sock.lock().unwrap(), 0x5d, health_pkt_c(1.0, c));
            return;
        }
    }
    drop(inv);
}
// Both death-protection paths own the effect guard; do not acquire it here.
fn totem_effects(ef: &mut Vec<Eff>) {
    ef.clear();
    // Vanilla grants 900 / 100 / 800 game ticks. At 20TPS a server tick is a game
    // tick, so these are also the stored server-tick values and the wire takes
    // them unchanged; there is no conversion left to apply.
    for (name, amp, dur) in [
        ("regeneration", 1, 900),
        ("absorption", 1, 100),
        ("fire_resistance", 0, 800),
    ] {
        let id = name_to_effect(name).expect("totem effect must exist in the effect registry");
        ef.push(Eff {
            id,
            amp,
            left: server_ticks(dur) as i32,
        });
    }
}
fn grant_totem_effects(c: &Client, ef: &mut Vec<Eff>) {
    for e in ef.iter() {
        let packet = remove_effect_pkt(c.eid, e.id);
        if let Ok(mut w) = c.sock.lock() {
            let _ = send_packet(&mut w, 0x43, packet.clone());
        }
        broadcast_seen(c.eid, |_| (0x43, packet.clone()));
    }
    totem_effects(ef);
    *c.absorb.lock().unwrap() = 8.0;
    for e in ef.iter() {
        // The wire uses game ticks even while the simulation stores server ticks.
        let packet = entity_effect_pkt(c.eid, e.id, e.amp, e.left);
        if let Ok(mut w) = c.sock.lock() {
            let _ = send_packet(&mut w, 0x76, packet.clone());
        }
        broadcast_seen(c.eid, |_| (0x76, packet.clone()));
    }
}
fn armor_pts_of(inv: &HashMap<i16, Stack>) -> i32 {
    let mut pts = 0i32;
    let slots: [(i16, &[(&str, i32)]); 4] = [
        (
            5,
            &[
                ("leather_helmet", 1),
                ("golden_helmet", 2),
                ("chainmail_helmet", 2),
                ("iron_helmet", 2),
                ("diamond_helmet", 3),
                ("netherite_helmet", 3),
                ("turtle_helmet", 2),
            ],
        ),
        (
            6,
            &[
                ("leather_chestplate", 3),
                ("golden_chestplate", 5),
                ("chainmail_chestplate", 5),
                ("iron_chestplate", 6),
                ("diamond_chestplate", 8),
                ("netherite_chestplate", 8),
                ("elytra", 0),
            ],
        ),
        (
            7,
            &[
                ("leather_leggings", 2),
                ("golden_leggings", 3),
                ("chainmail_leggings", 4),
                ("iron_leggings", 5),
                ("diamond_leggings", 6),
                ("netherite_leggings", 6),
            ],
        ),
        (
            8,
            &[
                ("leather_boots", 1),
                ("golden_boots", 1),
                ("chainmail_boots", 1),
                ("iron_boots", 2),
                ("diamond_boots", 3),
                ("netherite_boots", 3),
            ],
        ),
    ];
    for (slot, mats) in slots {
        if let Some((item, _, _)) = inv.get(&slot) {
            for (n, p) in mats {
                if name_to_item(n) == Some(*item) {
                    pts += p
                }
            }
        }
    }
    pts
}

